{"content": "from fastapi import FastAPI, Form
from fastapi.testclient import TestClient
from typing import Optional

app = FastAPI()

@app.post("/submit")
async def submit(age: Optional[int] = Form(None)):
    return {"age": age}

client = TestClient(app)

def test_empty_string_form_value():
    # Sending an empty string for an Optional[int] should result in None
    # because empty strings in HTML forms often mean "not provided".
    response = client.post("/submit", data={"age": ""})
    print(f"Status code: {response.status_code}")
    print(f"Response body: {response.text}")
    assert response.status_code == 200
    assert response.json() == {"age": None}

if __name__ == "__main__":
    try:
        test_empty_string_form_value()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        raise e
", "filepath": "_check.py"}

